import {allCardInstanceIds,createGame,gameStats,transition,viewFor,type GameCommand,type GameState} from '@madou/engine';
import {getAction} from '@madou/catalog';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export function makeR6CombinedSuppressionScenario(players:{id:string;name:string}[],revived=false):GameState{
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,'侍大将のシン');assignCharacter(s,b,'大神官ジル');assignCharacter(s,c,'破壊神ヴァンミール');assignCharacter(s,d,'邪祭ウーノス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};s.players[c]!.revealed=true;s.players[a]!.damage=gameStats(s,a).endurance-4;
 const first=takeCard(s,a,'黒翼飛翔剣'),lethal=takeCard(s,b,'踏み込み／弓'),revive=takeCard(s,d,'復活'),next=takeCard(s,a,'手裏剣');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!==next);for(const id of [a,b,c,d]){trimHand(s,id,...[first,lethal,revive].filter(x=>s.players[id]!.hand.includes(x)));while(s.players[id]!.hand.length<5){const i=s.deck.findIndex(x=>getAction(x)!.category!=='open');s.players[id]!.hand.push(s.deck.splice(i,1)[0]!);}}const prefix=s.deck.filter(id=>getAction(id)!.category!=='open').slice(0,2);s.deck=[...prefix,next,...s.deck.filter(id=>!prefix.includes(id)&&getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`COMBINED_SUPPRESSION_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('COMBINED_SUPPRESSION_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('COMBINED_SUPPRESSION_CARDS');}
 function until(done:()=>boolean){for(let n=0;n<400;n++){if(done())return;const w=s.windows!.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('COMBINED_SUPPRESSION_WINDOW');}
 function nextOwn(owner:string){for(let n=0;n<60;n++){const id=s.seatOrder[s.turnSeat]!;if(s.phase==='action'){if(id===owner)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment'){act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==revive).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});until(()=>!s.windows?.length);}else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error(`COMBINED_SUPPRESSION_TURN_${s.phase}`);}throw Error('COMBINED_SUPPRESSION_TURN_LIMIT');}
 readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});act(a,{type:'ATTACK',cardInstanceId:first,targetIds:[b],dedicated:false});until(()=>s.windows?.at(-1)?.kind==='effect-level');if(!revived)return s;
 const spirit=viewFor(s,a).abilityOptions.find(o=>o.abilityId==='c2-p01-r2c1-ab03')!;act(a,{type:'USE_ABILITY',abilityId:spirit.abilityId,targetEventId:spirit.targetEventId});until(()=>s.windows?.at(-1)?.kind==='damage'&&s.windows.at(-1)!.participants[s.windows.at(-1)!.cursor]===c);const ban=viewFor(s,c).abilityOptions.find(o=>o.abilityId==='c2-p07-r1c2-ab03')!;act(c,{type:'USE_ABILITY',abilityId:ban.abilityId,targetEventId:ban.targetEventId,targetIds:[a]});until(()=>!s.windows?.length);nextOwn(b);act(b,{type:'ATTACK',cardInstanceId:lethal,targetIds:[a],dedicated:false});until(()=>!s.windows?.length);nextOwn(d);act(d,{type:'PLAY_TURN_TECHNIQUE',cardInstanceId:revive,targetIds:[a],dedicated:true});until(()=>s.windows?.at(-1)?.kind==='re-setup');act(a,{type:'PASS_SETUP'});until(()=>!s.windows?.length);nextOwn(a);act(a,{type:'ATTACK',cardInstanceId:next,targetIds:[c],dedicated:false});until(()=>s.windows?.at(-1)?.kind==='effect-level');return s;
}
